with server.conn() as c:
 d=json.loads(c.execute("select document from brand_reports where brand_id='shilucheng'").fetchone()[0]);s=d['sections'][4]
 sel=record(c,5,server.TOPICS[5][0],'品牌选择证据的边界：产品认同先于品牌心智结论','综合官网价值表达、目标床单评论证据摘记和已选视频：可观察到的是材料/舒适承诺、具体产品体验以及部分复购。当前选例没有形成足够证据证明消费者普遍因Shilucheng品牌而买，或愿意为品牌名称支付溢价。不能把暂未证明品牌心智写成“品牌没有心智”。品牌判断仍需跨单品、跨渠道的购买理由和同规格价格证据。',[1,3,51,56,57,58,59,60],kind='分析',status='研究草稿')
 cap=record(c,5,server.TOPICS[5][1],'已看到的经营组合与尚未证明的壁垒','公开证据支持的经营组合包括：多材料多规格商品、多个线上销售入口、佣金达人素材、目标链接累计成交积累，以及部分消费者的产品复购自述。它们共同构成一个值得研究的经营系统，但不是长期壁垒的证明。材料、舒适主张和视频结构可被模仿；其供货一致性、达人复用效率、获客成本和退货后的盈利状况仍缺验证。不能由规模倒推研发或组织领先。',[15,3,4,51,27,56,57,58,59,60,45],kind='分析',status='研究草稿')
 s.update(headline='可见的是商品、内容与渠道的组合，尚未证明品牌溢价或技术壁垒',summary='现有证据更适合把Shilucheng当作一个成熟商品经营样本来拆解：它把材料与舒适组织成购买理由，通过多渠道和达人触达消费者，并出现产品复购线索。品牌心智、利润质量与难以复制的能力，需要另外验证。',boundary='这是基于公开材料的阶段性解释，不把一个床单的表现推广到整个品牌，也不因尚未证明就断言某项能力不存在。')
 edit(s['topics'][0],'消费者对具体产品的认可已经可见，对品牌本身的选择仍需单独验证。',['复购原文能够支持“这套床单值得再买”；不自动支持“消费者愿意为Shilucheng支付更多”。','达人包装露出建立识别线索，但五条视频不能证明品牌已形成稳定心智。'],refs=[21,sel],kind='分析判断',gap='跨单品品牌认知、品牌驱动购买和支付溢价没有可靠证据。')
 edit(s['topics'][1],'需要解释的是这套经营组合怎样高效运转，而不只是它使用了什么材料。',['已有长处：商品供给丰富、渠道入口齐备、达人表达能把材料转成使用场景。','需要追问：规格与颜色扩张后能否保持体验一致，内容带来的订单能否沉淀为有利润的复购。'],refs=[22,cap],kind='分析判断',gap='获客成本、退货率、复购率、盈利及供应链效率未披露；不认定长期壁垒。')
