with server.conn() as c:
 d=json.loads(c.execute("select document from brand_reports where brand_id='shilucheng'").fetchone()[0]);s=d['sections'][5]
 bodies=[
 ('产品创新','把“凉感床单”拆成能兑现的三项体验','现有消费者证据支持研究触感、热湿体验、床垫固定三个独立问题。研发对照应包括洗涤前后、不同颜色/批次和床垫加垫后的实际高度；仅提高竹材料比例不是已证明的解决方案。CGK已有100%竹源粘胶路线，所以“纯竹”不能单独构成新增机会。',[3,51,54,55]),
 ('营销与渠道借鉴','优先测试替换理由，而不是复制夸大的材料词','素材采用旧床品痛点→实际使用对照→清楚产品信息的结构。可测试已有产品的传播，不预设先开发新品；应看成交及退货后的结果，而不只看点赞。不能照搬“全天然”“抗菌”或否定其他材质健康属性的无证据表述。',[27,56,57,58,59,60,61]),
 ('竞争短板','竞争的薄弱处是承诺与交付之间可能存在的落差','三条达人素材的全天然竹表达、商品页60/40混纺信息与若干评论的材料预期落差可以相互对照。另有消费者报告不同颜色触感差异。它们构成值得实物核验的脆弱点，不证明普遍质量缺陷；也不能据此断言我方已经更好。',[3,51,58,59,60]),
 ('潜在市场机会','待验证命题：给怕热且换过床单仍失望的人，更可验证的升级理由','目标需求：已有床单使用后仍热、脱角或触感不稳定。证据来自特定评论，而非已测量人群规模。竞争：CGK的100%竹源粘胶、LDC混纺等已有供给，不能称为市场空白。差别必须落在可复核的持续体验上。市场规模：单链接累计成交无明确期间，不可据此计算美国市场或可获得收入。溢价：只有同规格、同促销条件下的支付意愿与成交测试才能证明，投诉不等于愿多付钱。我方条件：需要Breescape现有产品、检测结果、成本和渠道承接能力；本库目前未建立这条证据链。结论：值得列为验证命题，尚不支持立项或收入承诺。',[3,51,54,55,58,59,60]),
 ('对我方的战略启示','先找到可证明的体验差别，再决定做传播还是做新品','顺序建议：用已售产品与竞品做实际体验对照；如果我方已有稳定优势，先把它变成有证据的替换理由。如果没有优势，再判断供应链改进能否以目标成本完成。没有竞争领先和付费证据时，不建议仅凭“凉感”“纯竹”扩充SKU。该建议限定为研究与测试优先级，不是已经验证的商业机会。',[3,51,54,55,56,57,58,59,60])]
 ids=[]
 for topic,title,body,evidence in bodies:ids.append(record(c,6,topic,title,body,evidence,kind='分析',status='研究草稿'))
 s.update(headline='优先验证“承诺兑现”的竞争机会，先别把换材料当成增长答案',summary='这轮新增的机会判断，是把竞争焦点从材料名称转向持续使用结果：消费者为何想换、我方究竟在哪一点更好、这种好是否值得付更多。传播结构已有可测试的借鉴；新品机会仍需跨过性能、需求规模与利润三道验证。',boundary='本节为研究启示与待验证机会，不作市场规模、销售增量或我方能力的既成结论。')
 findings=[
 ('值得验证：把热湿体验、洗后触感与床角固定分别做到更稳定。',['不把“提高竹含量”直接当成创新；竞争者已经在卖100%竹源粘胶。'],'跨颜色/洗涤/床垫高度的实测尚缺。'),
 ('可先测试：围绕现有床单的具体不满，呈现可信的替换理由。',['用真实对照承接内容承诺；评估成交与退货，不只看点赞。'],'缺少我方内容测试和成交结果，尚非确定有效的投放方案。'),
 ('已发现风险线索：材料表达与实物信息之间存在可核对的落差。',['不同颜色触感差异是消费者自述，需核验后才能作为产品改进依据。'],'不能从个别评论推断普遍缺陷。'),
 ('机会命题：服务“已经换过，却仍不满意”的床单升级需求。',['竞争已存在；胜点必须是可验证的持续体验。','规模尚未测量、支付溢价尚未证明；Breescape的性能、成本和渠道承接能力仍需对照。'],'不能据单链接累计销量估算市场或承诺收入，暂不作为新品立项建议。'),
 ('先比较实物；已有优势做传播，能力缺口再决定是否开发。',[],'对我方的实测及商业可行性证据仍待补。')]
 for t,r,(f,b,g) in zip(s['topics'],ids,findings):edit(t,f,b,refs=[r],features=[],kind='分析判断',gap=g)
